<section class="password-section"><h2>Změna hesla</h2><form class="panel" method="post" action="/?admin=1"><?= csrf_field() ?><input type="hidden" name="action" value="password"><label>Současné heslo<input type="password" name="current_password" autocomplete="current-password" required></label><div class="form-row"><label>Nové heslo (alespoň 12 znaků)<input type="password" name="new_password" autocomplete="new-password" minlength="12" maxlength="72" required></label><label>Zopakovat nové heslo<input type="password" name="repeat_password" autocomplete="new-password" minlength="12" maxlength="72" required></label></div><button class="secondary-button">Změnit heslo</button></form></section>